{
  "story": "A random forest builds many distinct decision trees. Each tree casts an individual vote on the target class. The forest aggregates these votes using majority rule. The final predicted class emerges clearly.",
  "aha": {
    "stateId": "aggregate",
    "observation": "Majority voting outweighs minority errors to establish the robust final prediction."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Forest Step",
      "options": [
        "Tree 1",
        "Tree 2",
        "Tree 3",
        "Aggregation"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Random Forest Voting",
        "regions": [
          {
            "id": "treeA",
            "label": "Tree 1",
            "values": ["Class A"]
          },
          {
            "id": "treeB",
            "label": "Tree 2",
            "values": ["Class A"]
          },
          {
            "id": "treeC",
            "label": "Tree 3",
            "values": ["Class B"]
          },
          {
            "id": "forest",
            "label": "Final Forest",
            "values": ["Class A"]
          }
        ],
        "states": [
          {
            "id": "tree1",
            "label": "Step 1",
            "sentence": "Tree 1 votes for Class A.",
            "why": "Learns from a random feature subset.",
            "active": ["treeA"],
            "calloutRegion": "treeA",
            "readouts": [
              {
                "id": "v1",
                "label": "Tree 1 Vote",
                "value": "Class A"
              }
            ]
          },
          {
            "id": "tree2",
            "label": "Step 2",
            "sentence": "Tree 2 votes for Class A.",
            "why": "Different bootstrap sample produces matching vote.",
            "active": ["treeB"],
            "calloutRegion": "treeB",
            "readouts": [
              {
                "id": "v2",
                "label": "Tree 2 Vote",
                "value": "Class A"
              }
            ]
          },
          {
            "id": "tree3",
            "label": "Step 3",
            "sentence": "Tree 3 votes for Class B.",
            "why": "Variance introduces an outlier vote.",
            "active": ["treeC"],
            "calloutRegion": "treeC",
            "readouts": [
              {
                "id": "v3",
                "label": "Tree 3 Vote",
                "value": "Class B"
              }
            ]
          },
          {
            "id": "aggregate",
            "label": "Step 4",
            "sentence": "Majority rule combines all votes into Class A.",
            "why": "Two votes for A versus one for B yields A.",
            "active": ["forest"],
            "calloutRegion": "forest",
            "readouts": [
              {
                "id": "v4",
                "label": "Final Output",
                "value": "Class A (2/3)"
              }
            ]
          }
        ]
      }
    ]
  }
}
